{
  "labels": [
    {
      "i": 0,
      "speaker": "caller",
      "text": "Hello गुरमुख जी आपको King Durga Blankets OM 140 by 230 CM 2200 G की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "जी।"
    },
    {
      "i": 2,
      "speaker": "caller",
      "text": "ठीक है।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "ठीक है मैं Tanya बोल रही हूं IndiaMART से।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "हमारे पास कई अच्छे sellers available हैं जिनसे मैं आपको connect करवाऊंगी।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "बस कुछ details confirm कर दीजिए।"
    },
    {
      "i": 6,
      "speaker": "bot",
      "text": "आपको कितने piece चाहिए?"
    },
    {
      "i": 7,
      "speaker": "caller",
      "text": "एक piece से।"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "बहुत बढ़िया।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "अब बताइए bed size में single चाहिए या double?"
    },
    {
      "i": 10,
      "speaker": "caller",
      "text": "single."
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "समझ गई।"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "अब material में कौन सा चाहिए?"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "wool या fleece या कुछ और?"
    },
    {
      "i": 14,
      "speaker": "caller",
      "text": "ठंड रुकनी चाहिए।"
    },
    {
      "i": 15,
      "speaker": "caller",
      "text": "दो kg का है ये।"
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "बहुत बढ़िया आपने बताया ठंड रुकनी चाहिए और 2 kg का चाहिए।"
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "seller आपको सही option suggest कर देंगे।"
    },
    {
      "i": 18,
      "speaker": "bot",
      "text": "आपको मैं seller details WhatsApp पे भेज दूंगी जिनसे आप details और price discuss कर सकते हैं।"
    }
  ]
}
